import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { resolve, extname, sep } from 'node:path';
const root=process.cwd();
const types={'.html':'text/html','.mjs':'text/javascript','.js':'text/javascript','.css':'text/css','.json':'application/json'};
const server=http.createServer(async(req,res)=>{
 try {
  const url=new URL(req.url,'http://localhost');
  const name=decodeURIComponent(url.pathname)==='/'?'/index.html':decodeURIComponent(url.pathname);
  const file=resolve(root,'.'+name);
  if(!file.startsWith(root+sep)){res.writeHead(403).end();return;}
  const body=await readFile(file);
  res.writeHead(200,{'content-type':types[extname(file)]||'application/octet-stream','cache-control':'no-store'});res.end(body);
 }catch{res.writeHead(404).end('Not found');}
});
server.listen(Number(process.argv[2]),'127.0.0.1');

src/app.mjs.text:
import { invitations, overview as initialOverview } from './data.mjs';
import { sendInvitation, readOverview } from './transport.mjs';

const app = document.querySelector('#app');
const state = {
  rows: [...invitations],
  overview: initialOverview,
  email: '',
  note: '',
  message: '',
  sendError: '',
  overviewError: '',
  sending: false,
  refreshingOverview: false,
};

function element(tag, text) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  return node;
}

function restoreListFocus(target) {
  if (!target) return;
  const row = app.querySelector(`[data-invite-id="${target.inviteId}"]`);
  row?.querySelector(`[data-action="${target.action}"]`)?.focus();
}

function moveInvitation(inviteId, delta, action) {
  const position = state.rows.findIndex(row => row.id === inviteId);
  const nextPosition = position + delta;
  if (nextPosition < 0 || nextPosition >= state.rows.length) return;

  [state.rows[position], state.rows[nextPosition]] = [state.rows[nextPosition], state.rows[position]];
  draw({ inviteId, action });
}

async function refreshOverview({ render = true } = {}) {
  state.refreshingOverview = true;
  try {
    state.overview = await readOverview();
    state.overviewError = '';
  } catch {
    state.overviewError = 'Overview unavailable. Try refreshing again.';
  } finally {
    state.refreshingOverview = false;
    if (render) draw();
  }
}

async function submitInvitation(event) {
  event.preventDefault();
  if (state.sending) return;

  const submittedEmail = state.email;
  state.sending = true;
  state.sendError = '';
  state.message = '';
  // Keep the current DOM in place while the request is pending so a user can
  // continue working in the note and list without replacing their active control.
  event.currentTarget.querySelector('button[type="submit"]').disabled = true;

  try {
    const result = await sendInvitation(submittedEmail);
    state.rows.push(result.invitation);
    state.message = `Invitation accepted for ${result.invitation.email}.`;
    if (state.email === submittedEmail) state.email = '';
    await refreshOverview({ render: false });
  } catch {
    state.sendError = 'Invitation failed. Check the email and try again.';
    state.message = '';
    state.sending = false;
    draw();
    return;
  }

  state.sending = false;
  draw();
}

function draw(focusTarget) {
  app.replaceChildren(element('h1', 'Team invitations'));

  const form = element('form');
  const emailLabel = element('label', 'Email');
  const input = element('input');
  input.type = 'email';
  input.required = true;
  input.value = state.email;
  input.name = 'email';
  input.oninput = () => { state.email = input.value; };
  emailLabel.append(input);

  const submit = element('button', 'Send invitation');
  submit.type = 'submit';
  submit.disabled = state.sending;
  form.append(emailLabel, submit);
  form.onsubmit = submitInvitation;
  app.append(form);

  const status = element('p', state.message);
  status.setAttribute('role', 'status');
  app.append(status);
  if (state.sendError) {
    const alert = element('p', state.sendError);
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }

  const section = element('section');
  section.className = 'overview';
  section.append(element('h2', 'Overview'));
  const total = element('p', `Pending: ${state.overview.pending}`);
  total.dataset.testid = 'overview';
  const refresh = element('button', 'Refresh overview');
  refresh.disabled = state.refreshingOverview;
  refresh.onclick = () => {
    refresh.disabled = true;
    refreshOverview();
  };
  section.append(total, refresh);
  if (state.overviewError) {
    const overviewAlert = element('p', state.overviewError);
    overviewAlert.setAttribute('role', 'alert');
    section.append(overviewAlert);
  }
  app.append(section);

  const list = element('ol');
  list.setAttribute('aria-label', 'Invitations');
  state.rows.forEach((row, index) => {
    const item = element('li');
    item.dataset.inviteId = row.id;
    item.append(element('span', row.email));
    [['Move earlier', -1, 'earlier'], ['Move later', 1, 'later']].forEach(([name, delta, action]) => {
      const button = element('button', name);
      button.dataset.action = action;
      button.disabled = index + delta < 0 || index + delta >= state.rows.length;
      button.onclick = () => moveInvitation(row.id, delta, action);
      item.append(button);
    });
    list.append(item);
  });
  app.append(list);

  const noteLabel = element('label', 'Team note');
  const textarea = element('textarea');
  textarea.value = state.note;
  textarea.oninput = () => { state.note = textarea.value; };
  noteLabel.append(textarea);
  app.append(noteLabel);
  restoreListFocus(focusTarget);
}

draw();

